def optimal(amount, coins):
    INF = float("inf")
    dp = [0] + [INF] * amount
    pick = [None] * (amount + 1)
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and 1 + dp[a - c] < dp[a]:
                dp[a] = 1 + dp[a - c]
                pick[a] = c
    used, a = [], amount
    while a > 0:
        used.append(pick[a])
        a -= pick[a]
    return used

