from collections import deque

def dp_distance(a, b):
    dp = list(range(len(b) + 1))
    for i, ca in enumerate(a, start=1):
        prev, dp[0] = dp[0], i
        for j, cb in enumerate(b, start=1):
            cur = dp[j]
            dp[j] = min(dp[j] + 1, dp[j - 1] + 1, prev + (ca != cb))
            prev = cur
    return dp[-1]

def bfs_distance(a, b):
    if a == b:
        return 0
    seen = {a}
    frontier = deque([(a, 0)])
    alphabet = set(a + b)
    while frontier:
        s, d = frontier.popleft()
        neighbors = []
        for i in range(len(s)):
            neighbors.append(s[:i] + s[i + 1:])                    # delete
            for ch in alphabet:
                neighbors.append(s[:i] + ch + s[i + 1:])           # substitute
        for i in range(len(s) + 1):
            for ch in alphabet:
                neighbors.append(s[:i] + ch + s[i:])               # insert
        for t in neighbors:
            if t == b:
                return d + 1
            if t not in seen:
                seen.add(t)
                frontier.append((t, d + 1))

